function mdRequest(url) { var last=null; for(var attempt=0; attempt<3; attempt++){ var r=http.get(url); if(r.ok){ try { return r.json(); } catch(e) { throw new Error('MangaDex 返回非 JSON 数据，可能遇到验证页面或网络问题'); } } last=r; if(r.status>=400 && r.status<500 && r.status!==429) break; } throw new Error('MangaDex 请求失败: HTTP '+(last?last.status:'?')+' '+(last?last.error:'')); }
function mdPick(o) { if(!o) return ''; return o.zh || o['zh-hk'] || o.en || o.ja || o['ja-ro'] || Object.values(o)[0] || ''; }
function mdTitle(m) { var a=m.attributes||{}, t=a.title||{}; if(t.zh) return t.zh; if(t['zh-hk']) return t['zh-hk']; var alts=a.altTitles||[]; for(var i=0;i<alts.length;i++){ var v=alts[i]||{}; if(v.zh) return v.zh; if(v['zh-hk']) return v['zh-hk']; } return mdPick(t); }
function mdStatus(s) { var m={ongoing:'连载中',completed:'已完结',hiatus:'休刊中',cancelled:'已取消'}; return m[s] || s || ''; }
function mdBook(m) { var a=m.attributes, rel=m.relationships||[], cover=rel.find(function(x){return x.type==='cover_art'}), authors=rel.filter(function(x){return x.type==='author'||x.type==='artist'}).map(function(x){return x.attributes && x.attributes.name}).filter(Boolean); return {name:mdTitle(m),author:authors.join(', '),intro:mdPick(a.description),status:mdStatus(a.status),kind:(a.tags||[]).map(function(t){return MD_TAGS[t.id] || mdPick(t.attributes.name)}).join(', '),coverUrl:cover && cover.attributes ? 'https://uploads.mangadex.org/covers/'+m.id+'/'+cover.attributes.fileName+'.512.jpg':'',bookUrl:'https://api.mangadex.org/manga/'+m.id,tocUrl:'https://api.mangadex.org/manga/'+m.id}; }
function mdLangChain(ctx) { var want=String(ctx.vars.language||'zh'), out=[want]; if(want.indexOf('zh')===0){ if(out.indexOf('zh')<0) out.push('zh'); if(out.indexOf('zh-hk')<0) out.push('zh-hk'); } if(out.indexOf('en')<0) out.push('en'); return out; }
function mdLangQuery(ctx) { return mdLangChain(ctx).map(function(l){return '&availableTranslatedLanguage[]='+encodeURIComponent(l)}).join(''); }
function search(ctx) { var p=Math.max(1,Number(ctx.page)||1); var d=mdRequest('/manga?limit=20&offset='+((p-1)*20)+'&title='+encodeURIComponent(ctx.key)+'&includes[]=cover_art&includes[]=author&includes[]=artist&contentRating[]=safe&contentRating[]=suggestive&contentRating[]=erotica'); return mdReadable(d.data, ctx).map(function(m) { var b=mdBook(m), key=String(ctx.key||'').toLowerCase(), names=[m.attributes.title].concat(m.attributes.altTitles||[]); for (var i=0;i<names.length;i++) { var values=Object.values(names[i]||{}); for (var k=0;k<values.length;k++) { if (key && typeof values[k]==='string' && values[k].toLowerCase().indexOf(key)>=0) { b.name=values[k]; return b; } } } return b; }); }
function detail(ctx) { return mdBook(mdRequest(ctx.book.bookUrl+'?includes[]=cover_art&includes[]=author&includes[]=artist').data); }
function mdFeed(base, lang, acc) { var offset=0; while(true) { var d=mdRequest(base+'/feed?limit=500&offset='+offset+'&translatedLanguage[]='+encodeURIComponent(lang)+'&order[chapter]=asc&order[volume]=asc&includes[]=scanlation_group&contentRating[]=safe&contentRating[]=suggestive&contentRating[]=erotica'); d.data.forEach(function(c){ var a=c.attributes; if(a.externalUrl || !a.pages) return; var n=(a.chapter==null||a.chapter==='')?null:Number(a.chapter); var chapNum=(n!=null && isFinite(n))?n:null; var ck=chapNum==null?('c:'+(a.volume||'')+'|'+String(a.chapter||'')+'|'+c.id):('n:'+String(a.chapter)); if(acc[ck]) return; acc[ck]={num:chapNum,seq:mdFeed.seq=(mdFeed.seq||0)+1,title:(a.volume?'卷'+a.volume+' ':'')+(a.chapter?'第'+a.chapter+'话 ':'')+(a.title||'')||'章节',url:'https://api.mangadex.org/at-home/server/'+c.id}; }); offset+=d.data.length; if(!d.data.length || offset>=d.total) break; if(offset>=10000) throw new Error('目录超过 API 分页上限，请缩小语言范围'); } }
function toc(ctx) { var base=ctx.book.tocUrl||ctx.book.bookUrl, chain=mdLangChain(ctx), acc={}; for(var i=0;i<chain.length;i++){ mdFeed(base, chain[i], acc); if(Object.keys(acc).length>0 && chain[i]!=='zh') break; } var arr=Object.keys(acc).map(function(k){return acc[k]}); arr.sort(function(a,b){ if(a.num==null&&b.num==null) return a.seq-b.seq; if(a.num==null) return 1; if(b.num==null) return -1; if(a.num!==b.num) return a.num-b.num; return a.seq-b.seq; }); if(!arr.length) throw new Error('当前语言没有可直接阅读的章节；可能无对应翻译或仅有外链，请尝试切换章节语言'); return arr.map(function(x){return {title:x.title,url:x.url}}); }
