function mdExplore(ctx) { var p=Math.max(1,Number(ctx.page)||1); var u=ctx.url; return mdReadable(mdRequest(u+'&limit=20&offset='+((p-1)*20)+'&includes[]=cover_art&includes[]=author&includes[]=artist&contentRating[]=safe&contentRating[]=suggestive&contentRating[]=erotica').data, ctx).map(mdBook); }
function mdReadable(items, ctx) { if(!items.length) return []; var q=mdLangChain(ctx).map(function(l){return '&translatedLanguage[]='+encodeURIComponent(l)}).join(''); var urls=items.map(function(m){return '/manga/'+m.id+'/feed?limit=1'+q+'&includeExternalUrl=0&includeEmptyPages=0&contentRating[]=safe&contentRating[]=suggestive&contentRating[]=erotica';}); var ok=function(r){ try { var d=r.json(); return Array.isArray(d.data) && d.data.some(function(c){return c.attributes && !c.attributes.externalUrl && c.attributes.pages>0;}); } catch(e) { return false; } }; var first=http.all(urls,{concurrency:6,failOnPartial:false}); var good=items.map(function(){return false}); items.forEach(function(m,i){ if(ok(first[i])) good[i]=true; }); return items.filter(function(m,i){return good[i]}); }
